 $_REQUEST['uniquesession'] = true; $_REQUEST['config'] = 'MAPDB'; set_time_limit(7200); require_once(__DIR__ . '../../../../app/init.php'); require_once(__DIR__ . '../../../../app/med/cisz/api.php'); require_once(__DIR__ . '../../../../app/med/cisz/addresses.php'); require_once(__DIR__ . '../../../../app/map/common/addresses.php'); header('Content-Type: text/plain; charset=utf-8'); header('X-Accel-Buffering: no'); header('Cache-Control: no-cache, no-store, must-revalidate'); ini_set('output_buffering', '0'); ini_set('zlib.output_compression', '0'); while (ob_get_level() > 0) { if (!ob_end_flush()) { break; } } ob_implicit_flush(true); echo str_repeat(' ', 4096) . "\n"; flush(); class med_cisz_syncAddresses { private $db; private $deleteDuplicates = true; public function doSync($params = []) { print "--- sync started ---\n"; $db = $this->db ? : $this->db = connectDb(); $api = new med_cisz_api(); $addresses = new med_cisz_addresses(); $mapAddresses = new map_common_addresses(); $rows = selectSql($db, <<<SQL
