} usort($group, function($a, $b) { return $a['addressCode'] <=> $b['addressCode']; }); $replaceId = $group[0]['addressCode']; for ($i = 1; $i < count($group); $i++) { $deleteId = $group[$i]['addressCode']; $duplicatesFound++; try { $result = $mapAddresses->replaceAddress((object)[ 'deleteId' => $deleteId, 'replaceId' => $replaceId, 'address' => "Дубль после синхронизации с ЦИСЗ, SOATO={$soato}", ]); if ($result === true) { $duplicatesDeleted++; } else { $duplicateErrors++; printf("[ОШИБКА] Не удалось удалить AddressCode=%d, SOATO=%s\n", $deleteId, $soato); } } catch (\Throwable $e) { $duplicateErrors++; printf("[ОШИБКА] AddressCode=%d, SOATO=%s: %s\n", $deleteId, $soato, $e->getMessage()); } } } print "--------------------------------------------------\n"; print "ИТОГИ УДАЛЕНИЯ ДУБЛЕЙ\n"; printf("Найдено дублей:       %d\n", $duplicatesFound); printf("Удалено с заменой:    %d\n", $duplicatesDeleted); printf("Ошибок удаления:      %d\n", $duplicateErrors); } print "--------------------------------------------------\n"; print "ИТОГИ СИНХРОНИЗАЦИИ\n"; printf("Успешно обработано:              %d\n", $successCount); printf("Ошибок:                          %d\n", $failedCount); printf("Не найдено в ЦИСЗ:               %d\n", $skippedCount); print "--- sync done ---\n"; } } $sync = new med_cisz_syncAddresses(); $sync->doSync();